#!/usr/bin/env python3
# Generated by sdk-kit 0.2.0 — do not edit; change sdk-kit and run "sdk-kit sync"
"""Release readiness checks for the Zipkin SDK (``make release-check``).

    release-check.py config       release-please config + manifest, version files, Go module
    release-check.py typescript   package.json metadata npm and provenance need
    release-check.py rust         crates.io metadata and dependency sources (cargo metadata)
    release-check.py go           go.mod module path, no replace directives, version.go
    release-check.py python       built wheel + sdist in python/dist (name, version)
    release-check.py java         jar, sources and javadoc jars, Maven Central POM metadata

Expected registry names come from ``.sdk-kit.json`` (the service entry of sdk-kit's
``spec/services.json``). Python 3.8+ standard library only. Exit 1 lists every problem.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
import xml.etree.ElementTree as ET
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
LANGS = ("typescript", "rust", "go", "python", "java")
UNRELEASED = "0.0.0"
SEMVER = re.compile(r"^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$")
OWNER = "grow-codes-packages"
KEY = "zipkin"
REPO_URL = f"https://github.com/{OWNER}/{KEY}"
RELEASE_TYPES = {"typescript": "node", "rust": "rust", "go": "go", "python": "python", "java": "java"}
# crates.io category slugs (https://crates.io/category_slugs) a client library may use.
CRATE_CATEGORIES = {
    "api-bindings", "asynchronous", "authentication", "caching", "config", "cryptography",
    "database", "development-tools", "development-tools::debugging", "development-tools::profiling",
    "development-tools::testing", "encoding", "network-programming", "parsing", "web-programming",
    "web-programming::http-client", "web-programming::websocket",
}  # fmt: skip
CRATE_KEYWORD = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,19}$")


def names() -> dict[str, str]:
    """Registry names of the five packages (``.sdk-kit.json`` service entry, else sdk-kit defaults)."""
    snake = "zipkin"
    found = {
        "npm": f"@grow-codes/{KEY}",
        "crate": f"grow-{KEY}",
        "pypi": f"grow-{KEY}",
        "pyImport": f"grow_{snake}",
        "goModule": f"github.com/{OWNER}/{KEY}/go",
        "maven": f"codes.grow.packages:{KEY}",
    }
    try:
        service = json.loads((ROOT / ".sdk-kit.json").read_text(encoding="utf-8")).get("service", {})
    except (OSError, ValueError, AttributeError):
        service = {}
    for name in found:
        value = service.get(name) if isinstance(service, dict) else None
        if isinstance(value, str) and value:
            found[name] = value
    return found


def package_names() -> dict[str, str]:
    n = names()
    return {
        "typescript": n["npm"],
        "rust": n["crate"],
        "go": n["goModule"],
        "python": n["pypi"],
        "java": n["maven"],
    }


def version_files() -> dict[str, str]:
    """The release-please ``extra-files`` per language (relative to the language folder)."""
    return {
        "typescript": "src/core/version.ts",
        "go": "version.go",
        "python": f"src/{names()['pyImport']}/_version.py",
        "java": "pom.xml",
    }


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def load_json(path: Path, problems: list[str]) -> dict:
    try:
        data = json.loads(read(path))
    except (OSError, ValueError) as exc:
        problems.append(f"{path.relative_to(ROOT)}: {exc}")
        return {}
    if not isinstance(data, dict):
        problems.append(f"{path.relative_to(ROOT)}: not a JSON object")
        return {}
    return data


def expected_version(lang: str) -> str | None:
    """Version the package must carry: the manifest one, or ``initial-version`` before the first release."""
    problems: list[str] = []
    manifest = load_json(ROOT / ".release-please-manifest.json", problems)
    config = load_json(ROOT / "release-please-config.json", problems)
    released = manifest.get(lang)
    if isinstance(released, str) and released != UNRELEASED:
        return released
    package = config.get("packages", {}).get(lang, {})
    initial = package.get("initial-version") if isinstance(package, dict) else None
    return initial if isinstance(initial, str) else None


def first(pattern: str, text: str) -> str | None:
    match = re.search(pattern, text, re.MULTILINE)
    return match.group(1) if match else None


def current_version(lang: str) -> str | None:
    """Version written in the package files of ``lang`` (None when it cannot be read)."""
    base = ROOT / lang
    try:
        if lang == "typescript":
            return json.loads(read(base / "package.json")).get("version")
        if lang == "rust":
            return first(r'^version\s*=\s*"([^"]+)"', read(base / "Cargo.toml"))
        if lang == "go":
            return first(r'Version\s*=\s*"([^"]+)"', read(base / "version.go"))
        if lang == "python":
            return first(r'__version__\s*=\s*"([^"]+)"', read(base / version_files()["python"]))
        return pom_text(ET.parse(base / "pom.xml").getroot(), "version")
    except (OSError, ValueError, ET.ParseError):
        return None


def check_config() -> list[str]:
    problems: list[str] = []
    config = load_json(ROOT / "release-please-config.json", problems)
    manifest = load_json(ROOT / ".release-please-manifest.json", problems)
    if not config:
        return problems
    packages = config.get("packages", {})
    if not isinstance(packages, dict):
        return [*problems, "release-please-config.json: 'packages' must be an object"]
    if config.get("separate-pull-requests") is not False:
        problems.append("release-please-config.json: separate-pull-requests must be false (one release PR)")
    wanted = package_names()
    extra = version_files()
    for lang in LANGS:
        pkg = packages.get(lang)
        where = f"release-please-config.json: packages.{lang}"
        if not isinstance(pkg, dict):
            problems.append(f"{where} missing")
            continue
        if pkg.get("package-name") != wanted[lang]:
            problems.append(f"{where}.package-name is {pkg.get('package-name')!r}, expected {wanted[lang]!r}")
        if pkg.get("release-type") not in (RELEASE_TYPES[lang], "maven" if lang == "java" else None):
            problems.append(f"{where}.release-type is {pkg.get('release-type')!r}, expected {RELEASE_TYPES[lang]!r}")
        if pkg.get("component", lang) != lang:
            problems.append(f"{where}.component must be {lang!r} (release-packages.yml reads {lang}--* outputs)")
        if lang in extra:
            files = [f if isinstance(f, str) else f.get("path") for f in pkg.get("extra-files", [])]
            if extra[lang] not in files:
                problems.append(f"{where}.extra-files must list {extra[lang]!r} (release-please bumps it)")
            path = ROOT / lang / extra[lang]
            if not path.is_file():
                problems.append(f"{lang}/{extra[lang]} missing")
            elif "x-release-please-version" not in read(path):
                problems.append(f"{lang}/{extra[lang]}: no x-release-please-version marker on the version line")
        version = manifest.get(lang)
        if not isinstance(version, str) or not SEMVER.match(version):
            problems.append(
                f".release-please-manifest.json: {lang!r} missing or not a version "
                f'(use "{UNRELEASED}" before the first release)'
            )
        expected, current = expected_version(lang), current_version(lang)
        if expected is None:
            problems.append(f"{where}: no initial-version and no released version in the manifest")
        elif current != expected:
            problems.append(f"{lang}: package version is {current!r}, release-please expects {expected!r}")
    ts_file = ROOT / "typescript" / version_files()["typescript"]
    ts_version = first(r'SDK_VERSION\s*=\s*"([^"]+)"', read(ts_file)) if ts_file.is_file() else None
    if ts_file.is_file() and ts_version != current_version("typescript"):
        problems.append(
            f"typescript: SDK_VERSION {ts_version!r} != package.json version {current_version('typescript')!r}"
        )
    go = packages.get("go", {})
    if isinstance(go, dict) and (go.get("tag-separator"), go.get("include-v-in-tag")) != ("/", True):
        problems.append('release-please-config.json: packages.go needs "tag-separator": "/" and '
                        '"include-v-in-tag": true (Go tags read go/vX.Y.Z)')  # fmt: skip
    problems += check_go_module()
    return problems


def check_typescript() -> list[str]:
    problems: list[str] = []
    pkg = load_json(ROOT / "typescript" / "package.json", problems)
    if not pkg:
        return problems
    want = names()["npm"]
    repo = pkg.get("repository") if isinstance(pkg.get("repository"), dict) else {}
    publish = pkg.get("publishConfig") if isinstance(pkg.get("publishConfig"), dict) else {}
    checks = [
        (pkg.get("name") == want, f"name is {pkg.get('name')!r}, expected {want!r}"),
        (not pkg.get("private"), '"private": true blocks npm publish'),
        (bool(pkg.get("description")), "description missing"),
        (pkg.get("license") == "Apache-2.0", "license must be Apache-2.0"),
        (publish.get("access") == "public", 'publishConfig.access must be "public" (scoped package)'),
        (
            repo.get("url") in (f"git+{REPO_URL}.git", f"{REPO_URL}.git", REPO_URL),
            f"repository.url must point to {REPO_URL} (npm provenance compares it with the build repo)",
        ),
        (repo.get("directory") == "typescript", 'repository.directory must be "typescript"'),
        (bool(pkg.get("files")), "files allowlist missing"),
    ]
    problems += [f"typescript/package.json: {msg}" for ok, msg in checks if not ok]
    version = first(r'SDK_VERSION\s*=\s*"([^"]+)"', read(ROOT / "typescript" / version_files()["typescript"]))
    if version != pkg.get("version"):
        problems.append(f"typescript: SDK_VERSION {version!r} != package.json version {pkg.get('version')!r}")
    return problems


def check_rust() -> list[str]:
    cargo = os.environ.get("CARGO", "cargo")
    try:
        out = subprocess.run(
            [cargo, "metadata", "--no-deps", "--format-version", "1"],
            cwd=ROOT / "rust", check=True, capture_output=True, text=True,
        ).stdout  # fmt: skip
    except (OSError, subprocess.CalledProcessError) as exc:
        return [f"rust: cargo metadata failed: {exc}"]
    want = names()["crate"]
    packages = [p for p in json.loads(out)["packages"] if p["name"] == want]
    if not packages:
        return [f"rust/Cargo.toml: package {want!r} not found"]
    pkg = packages[0]
    problems = [f"rust/Cargo.toml: {field} missing" for field in ("description", "license") if not pkg.get(field)]
    if pkg.get("license") and pkg["license"] != "Apache-2.0":
        problems.append("rust/Cargo.toml: license must be Apache-2.0")
    if (pkg.get("repository") or "").rstrip("/") != REPO_URL:
        problems.append(f"rust/Cargo.toml: repository must be {REPO_URL}")
    readme = pkg.get("readme")
    if not readme or not (Path(pkg["manifest_path"]).parent / readme).is_file():
        problems.append("rust/Cargo.toml: readme missing or the file does not exist")
    keywords = pkg.get("keywords") or []
    if len(keywords) > 5:
        problems.append(f"rust/Cargo.toml: {len(keywords)} keywords (crates.io allows 5)")
    problems += [f"rust/Cargo.toml: invalid keyword {k!r}" for k in keywords if not CRATE_KEYWORD.match(k)]
    categories = pkg.get("categories") or []
    if len(categories) > 5:
        problems.append(f"rust/Cargo.toml: {len(categories)} categories (crates.io allows 5)")
    problems += [
        f"rust/Cargo.toml: unknown crates.io category {c!r}" for c in categories if c not in CRATE_CATEGORIES
    ]
    for dep in pkg.get("dependencies", []):
        if dep.get("kind") == "dev":
            continue  # cargo publish strips dev-dependencies without a version
        source = dep.get("source") or ""
        if source.startswith("git+"):
            problems.append(f"rust/Cargo.toml: dependency {dep['name']!r} comes from git (not publishable)")
        elif dep.get("path") and dep.get("req") in (None, "", "*"):
            problems.append(f"rust/Cargo.toml: path dependency {dep['name']!r} needs a version")
    return problems


def check_go_module() -> list[str]:
    path = ROOT / "go" / "go.mod"
    if not path.is_file():
        return ["go/go.mod missing"]
    text = read(path)
    problems = []
    module = first(r"^module\s+(\S+)", text)
    if module != names()["goModule"]:
        problems.append(f"go/go.mod: module is {module!r}, expected {names()['goModule']!r}")
    if re.search(r"^\s*replace\b", text, re.MULTILINE):
        problems.append("go/go.mod: replace directives are ignored for dependants; remove them before a release")
    return problems


def check_go() -> list[str]:
    problems = check_go_module()
    expected, current = expected_version("go"), current_version("go")
    if current != expected:
        problems.append(
            f"go/version.go: Version is {current!r}, .release-please-manifest.json expects {expected!r}"
        )
    return problems


def check_python() -> list[str]:
    dist = ROOT / "python" / "dist"
    wheels, sdists = sorted(dist.glob("*.whl")), sorted(dist.glob("*.tar.gz"))
    if len(wheels) != 1 or len(sdists) != 1:
        return [f"python/dist: expected one wheel and one sdist, found {len(wheels)} and {len(sdists)} (run make pack)"]
    problems: list[str] = []
    with zipfile.ZipFile(wheels[0]) as wheel:
        meta_name = next((n for n in wheel.namelist() if n.endswith(".dist-info/METADATA")), None)
        if meta_name is None:
            return [f"{wheels[0].name}: no METADATA"]
        meta = wheel.read(meta_name).decode("utf-8")
        top = {n.split("/", 1)[0] for n in wheel.namelist()}
    name, version = first(r"^Name: (.+)$", meta), first(r"^Version: (.+)$", meta)
    norm = lambda s: re.sub(r"[-_.]+", "-", (s or "").lower())  # noqa: E731
    if norm(name) != norm(names()["pypi"]):
        problems.append(f"{wheels[0].name}: Name is {name!r}, expected {names()['pypi']!r}")
    if version != current_version("python"):
        problems.append(f"{wheels[0].name}: Version {version!r} != _version.py {current_version('python')!r}")
    if names()["pyImport"] not in top:
        problems.append(f"{wheels[0].name}: package {names()['pyImport']!r} not in the wheel")
    for field in ("Summary", "License-Expression", "Description-Content-Type"):
        if not re.search(rf"^{field}: \S", meta, re.MULTILINE):
            problems.append(f"{wheels[0].name}: METADATA {field} missing")
    if "Project-URL: Repository, " + REPO_URL not in meta:
        problems.append(f"{wheels[0].name}: Project-URL Repository {REPO_URL} missing")
    return problems


def pom_text(root: ET.Element, path: str) -> str | None:
    ns = {"m": "http://maven.apache.org/POM/4.0.0"}
    node = root.find("/".join(f"m:{p}" for p in path.split("/")), ns)
    return node.text.strip() if node is not None and node.text else None


def check_java() -> list[str]:
    base = ROOT / "java"
    root = ET.parse(base / "pom.xml").getroot()
    problems: list[str] = []
    group, artifact = names()["maven"].split(":", 1)
    if (pom_text(root, "groupId"), pom_text(root, "artifactId")) != (group, artifact):
        problems.append(f"java/pom.xml: coordinates must be {group}:{artifact}")
    # Maven Central requirements: https://central.sonatype.org/publish/requirements/
    required = [
        "name", "description", "url", "licenses/license/name", "licenses/license/url",
        "developers/developer/name", "scm/url", "scm/connection", "scm/developerConnection",
    ]  # fmt: skip
    problems += [f"java/pom.xml: <{p}> missing (Maven Central)" for p in required if not pom_text(root, p)]
    version = pom_text(root, "version")
    for suffix in ("", "-sources", "-javadoc"):
        jar = base / "target" / f"{artifact}-{version}{suffix}.jar"
        if not jar.is_file():
            problems.append(f"java/target/{jar.name} missing (run make release-check)")
    return problems


CHECKS = {
    "config": check_config,
    "typescript": check_typescript,
    "rust": check_rust,
    "go": check_go,
    "python": check_python,
    "java": check_java,
}


def main(argv: list[str]) -> int:
    if len(argv) != 1 or argv[0] not in CHECKS:
        print(f"usage: release-check.py {{{'|'.join(CHECKS)}}}", file=sys.stderr)
        return 2
    problems = CHECKS[argv[0]]()
    for problem in problems:
        print(f"release-check: {problem}", file=sys.stderr)
    if problems:
        return 1
    print(f"release-check {argv[0]}: OK")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
